package eu.simplexsmp.adminsuite;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Function;
import org.bukkit.entity.Player;
import org.bukkit.configuration.file.YamlConfiguration;

/** Separate persistent probe observations; never used as account identity or Alt evidence. */
final class ClientProbeHistory implements AutoCloseable {
    record Join(long at,String connection,String brand,String locale) { }
    record Scan(long at,String scan,String connection,String actor,boolean automatic,boolean diagnostic,
                String status,String brand,String locale,Map<String,String> results,Map<String,String> keys,
                String action,String detail) {
        Scan { results=Collections.unmodifiableMap(new LinkedHashMap<>(results));keys=Map.copyOf(keys); }
        String detected(Function<String,String> names){return results.entrySet().stream().filter(e->e.getValue().equals("DETECTED")).map(e->names.apply(e.getKey())).reduce((a,b)->a+", "+b).orElse("—");}
        String format(Function<String,String> names){return format(names,false);}
        String format(Function<String,String> names,boolean german){StringBuilder text=new StringBuilder(timestamp(at)+" • "+status+"\nScan: "+scan+"\nConnection: "+connection+"\n"+(automatic?"Join":"Manual")+" • "+actor+(diagnostic?" • Diagnostic only":"")+"\nBrand/Locale: "+ClientProbeDiagnostics.escaped(brand)+" / "+ClientProbeDiagnostics.escaped(locale)+"\nAction: "+action+"\n"+detail+"\n");for(var e:results.entrySet()){text.append("\n").append(e.getValue().equals("DETECTED")?"§c":e.getValue().equals("NOT_DETECTED")?"§a":"§e").append(e.getValue()).append(" §f").append(names.apply(e.getKey()));if(keys.containsKey(e.getKey()))text.append("\n§7Key: ").append(ClientProbeDiagnostics.escaped(keys.get(e.getKey())));}String value=text.toString();return german?value.replace("Connection:","Verbindung:").replace("Manual","Manuell").replace("Diagnostic only","Nur Diagnose").replace("Brand/Locale:","Brand/Sprache:").replace("Action:","Maßnahme:").replace("Key:","Schlüssel:"):value;}
    }
    private final SimplexAdminSuite plugin;
    private final Path file;
    private final ExecutorService writer=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"Simplex-client-history");t.setDaemon(true);return t;});
    private final Map<UUID,Join> joins=new LinkedHashMap<>();
    private final Map<UUID,Deque<Scan>> scans=new LinkedHashMap<>();
    ClientProbeHistory(SimplexAdminSuite p){plugin=p;file=p.getDataFolder().toPath().resolve("client-probe-history.yml");load();}
    void join(Player p,String connection){joins.put(p.getUniqueId(),new Join(System.currentTimeMillis(),connection,ClientProbeDiagnostics.brand(p),p.getLocale()));save();}
    List<Scan> entries(UUID id){List<Scan> copy=new ArrayList<>(scans.getOrDefault(id,new ArrayDeque<>()));Collections.reverse(copy);return List.copyOf(copy);}
    void record(Player p,String scan,String connection,String actor,boolean automatic,boolean diagnostic,String status,Map<String,ClientProbeManager.Result> results,Map<String,String> keys,ClientProbeRules.ActionReport action){Map<String,String> values=new LinkedHashMap<>();results.forEach((id,result)->values.put(id,result.name()));Deque<Scan> history=scans.computeIfAbsent(p.getUniqueId(),id->new ArrayDeque<>());Join joined=joins.get(p.getUniqueId());if(joined!=null&&joined.connection.equals(connection))joins.put(p.getUniqueId(),new Join(joined.at,connection,ClientProbeDiagnostics.brand(p),p.getLocale()));history.addLast(new Scan(System.currentTimeMillis(),scan,connection,actor,automatic,diagnostic,status,ClientProbeDiagnostics.brand(p),p.getLocale(),values,keys,action.action(),action.detail()));int maximum=Math.max(20,Math.min(4096,plugin.getConfig().getInt("client-security.probes.history-max-scans-per-player",256)));while(history.size()>maximum)history.removeFirst();save();}
    String connectionSummary(UUID id,Function<String,String> names){return connectionSummary(id,names,false);}
    String connectionSummary(UUID id,Function<String,String> names,boolean german){Join join=joins.get(id);if(join==null)return german?"Letzte Join-Prüfung: —":"Last join probe: —";Map<String,String> observed=new LinkedHashMap<>();for(Scan scan:scans.getOrDefault(id,new ArrayDeque<>()))if(scan.connection.equals(join.connection)&&!scan.diagnostic)for(var e:scan.results.entrySet())if(e.getValue().equals("DETECTED"))observed.put(e.getKey(),names.apply(e.getKey()));return (german?"Letzter Beitritt: ":"Last join: ")+timestamp(join.at)+" • Brand: "+ClientProbeDiagnostics.escaped(join.brand)+(german?"\nBeobachtete Mods in letzter Verbindung: ":"\nObserved mods in last connection: ")+(observed.isEmpty()?"—":String.join(", ",observed.values()));}
    void clear(UUID id)throws IOException{Deque<Scan> old=scans.remove(id);Join join=joins.remove(id);try{YamlConfiguration snapshot=snapshot();writer.submit(()->{try{write(snapshot);}catch(IOException e){throw new UncheckedIOException(e);}}).get(5,TimeUnit.SECONDS);}catch(InterruptedException|ExecutionException|TimeoutException e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();if(old!=null)scans.put(id,old);if(join!=null)joins.put(id,join);throw new IOException("History clear failed",e);}}
    private void save(){YamlConfiguration snapshot=snapshot();writer.execute(()->{try{write(snapshot);}catch(IOException e){plugin.getLogger().warning("Client scan history could not be saved: "+e.getMessage());}});}
    private YamlConfiguration snapshot(){YamlConfiguration y=new YamlConfiguration();y.set("schema",1);for(var e:joins.entrySet()){String path="players."+e.getKey()+".join";y.set(path+".at",e.getValue().at);y.set(path+".connection",e.getValue().connection);y.set(path+".brand",e.getValue().brand);y.set(path+".locale",e.getValue().locale);}for(var e:scans.entrySet())y.set("players."+e.getKey()+".scans",e.getValue().stream().map(ClientProbeHistory::encode).toList());return y;}
    private void write(YamlConfiguration y)throws IOException{Files.createDirectories(file.getParent());Path temp=Files.createTempFile(file.getParent(),"probe-history-",".tmp");try{y.save(temp.toFile());try{Files.move(temp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException unsupported){Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
    private void load(){if(!Files.exists(file))return;YamlConfiguration y=YamlConfiguration.loadConfiguration(file.toFile());var players=y.getConfigurationSection("players");if(players==null)return;for(String raw:players.getKeys(false))try{UUID id=UUID.fromString(raw);String path="players."+raw;if(y.contains(path+".join"))joins.put(id,new Join(y.getLong(path+".join.at"),y.getString(path+".join.connection",""),y.getString(path+".join.brand",""),y.getString(path+".join.locale","")));Deque<Scan> history=new ArrayDeque<>();for(String line:y.getStringList(path+".scans"))try{history.addLast(decode(line));}catch(RuntimeException invalid){plugin.getLogger().warning("Invalid saved client scan for "+id+"; remaining entries kept.");}scans.put(id,history);}catch(IllegalArgumentException invalid){plugin.getLogger().warning("Invalid client-history player id ignored.");}}
    @Override public void close(){writer.shutdown();try{if(!writer.awaitTermination(5,TimeUnit.SECONDS))plugin.getLogger().warning("Client history is still finishing writes.");}catch(InterruptedException e){Thread.currentThread().interrupt();}}
    static String timestamp(long at){return java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss").withZone(java.time.ZoneId.systemDefault()).format(java.time.Instant.ofEpochMilli(at));}
    static String encode(Scan s){Map<String,Object> values=new LinkedHashMap<>();values.put("at",s.at);values.put("scan",s.scan);values.put("connection",s.connection);values.put("actor",s.actor);values.put("automatic",s.automatic);values.put("diagnostic",s.diagnostic);values.put("status",s.status);values.put("brand",s.brand);values.put("locale",s.locale);values.put("results",s.results);values.put("keys",s.keys);values.put("action",s.action);values.put("detail",s.detail);return DiscordBotManager.Json.stringify(values);}
    static Scan decode(String json){Object parsed=DiscordBotManager.Json.parse(json);if(!(parsed instanceof Map<?,?> m))throw new IllegalArgumentException();return new Scan(((Number)m.get("at")).longValue(),text(m,"scan"),text(m,"connection"),text(m,"actor"),Boolean.TRUE.equals(m.get("automatic")),Boolean.TRUE.equals(m.get("diagnostic")),text(m,"status"),text(m,"brand"),text(m,"locale"),strings(m.get("results")),strings(m.get("keys")),text(m,"action"),text(m,"detail"));}
    private static String text(Map<?,?> m,String key){return Objects.toString(m.get(key),"");}
    private static Map<String,String> strings(Object value){Map<String,String> out=new LinkedHashMap<>();if(value instanceof Map<?,?> map)map.forEach((k,v)->out.put(Objects.toString(k,""),Objects.toString(v,"")));return out;}
}
